const SAMPLE_ITEMS = 3;
const shorten = (value: unknown): unknown => Array.isArray(value)
  ? [...value.slice(0, SAMPLE_ITEMS).map(shorten), ...value.length > SAMPLE_ITEMS ? [`… ${value.length - SAMPLE_ITEMS} more`] : []]
  : value && typeof value === "object" ? Object.fromEntries(Object.entries(value).map(([key, item]) => [key, shorten(item)])) : value;
const sample = (data: unknown) => { const json = JSON.stringify(shorten(data), null, 1); return json.length > 24000 ? `${json.slice(0, 24000)}\n… (truncated)` : json; };

async function design(run: Run, system: string, prompt: string) {
  const model = await modelForSettings(run.context.settings, "artifacts");
  const { text } = await generateText({
    model, instructions: system, prompt, maxOutputTokens: 32000,
    providerOptions: { openai: { reasoningEffort: "low" } },
    abortSignal: AbortSignal.any([run.signal, AbortSignal.timeout(200_000)]),
  });
  return { text: unfence(text), model: model.modelId };
}

async function nextVersion(supabase: SupabaseClient, table: "artifact_versions" | "artifact_card_versions", column: "artifact_id" | "card_id", id: string, workspaceId: string) {
  const { data, error } = await supabase.from(table).select("version").eq("workspace_id", workspaceId).eq(column, id).order("version", { ascending: false }).limit(1).maybeSingle();
  if (error) throw error;
  return ((data?.version as number | undefined) ?? 0) + 1;
}

const today = (context: Context) => calendarDate(new Date(), context.settings.timezone);

async function writePage(run: Run, input: { title: string; brief: string; queries: ArtifactQuery[]; fixedDates?: boolean }) {
  const { context, artifactId } = run;
  const { supabase, workspace } = context;
  const errors = [...frozenDates(input.queries, input.fixedDates), ...checkQueries(input.queries, today(context))];
  if (errors.length) return { saved: false, errors };
  const [data, current] = await Promise.all([
    runArtifactQueries(input.queries, context, today(context)),
    supabase.from("artifact_versions").select("version, html").eq("workspace_id", workspace.id).eq("artifact_id", artifactId).order("version", { ascending: false }).limit(1).maybeSingle(),
  ]);
  if (current.error) throw current.error;
  let prompt = `${current.data ? `Current page (change it as the brief says, keep the rest):\n${current.data.html}\n\n` : ""}Brief:\n${input.brief}\n\nQueries:\n${JSON.stringify(input.queries)}\n\nData now (window.MONEO_DATA):\n${sample(data)}`;
  // A page whose script doesn't parse draws nothing, so it is never saved; the designer gets two chances to fix it
    if (!await enterStage(db, jobId, workspaceId, runId, "writing_review")) return null;
    const settings = await loadWorkspaceSettings(db, workspaceId);
    if (!await summaryStillEnabled(db, jobId, workspaceId, settings, scheduled)) return null;
    reviewScopes(settings, !("unavailable" in evidence.planning), evidence.sourceCoverage?.importStatuses != null);
    const receipts: EvidenceReceipt[] = [];
    for (const id of evidence.verification.receiptIds) {
      const receipt = await loadEvidenceReceipt(db, workspaceId, id);
      if (!receipt) throw new FatalError("Retained review evidence is unavailable");
      requireAiScope(settings, ...receipt.scopes);
      receipts.push(receipt);
    }
    const model = await modelForSettings(settings, "review");
    // Recheck after asynchronous preparation, before submitting financial context.
    if (!await enterStage(db, jobId, workspaceId, runId, "writing_review")) return null;
    monitoring = (async () => {
      while (!finished.signal.aborted) {
        await delay(500, undefined, { signal: finished.signal });
        const job = await db.from("background_jobs").select("status, cancel_requested, workflow_run_id")
          .eq("id", jobId).eq("workspace_id", workspaceId).abortSignal(AbortSignal.any([finished.signal, AbortSignal.timeout(2000)])).single();
        if (finished.signal.aborted) return;
        if (job.error) throw job.error;
        if (job.data.cancel_requested || job.data.workflow_run_id !== runId || !["queued", "running"].includes(job.data.status)) {
          stopped.abort(new Error("Financial review stopped"));
          return;
        }
      }
    })().catch(error => {
      if (!finished.signal.aborted) { monitoringError = error; stopped.abort(error); }
    });
    if (evidence.reviewInvestigation) {
      const current = await db.from("background_jobs").select("review_progress").eq("id", jobId).eq("workspace_id", workspaceId).single();
      if (current.error) throw current.error;
      const progress: ReviewProgress = current.data.review_progress ?? evidence.reviewInvestigation.progress;
      const priorityIds = evidence.reviewInvestigation.progress.queries.flatMap(query => query.result?.groups.flatMap(group =>
        ["current", "comparison", "delta"].map(kind => `${evidenceFingerprint(group.key).slice(0, 32)}:${kind}`)) ?? []);
      const input = buildReviewPrompt(evidence.reviewInvestigation.request, receipts, progress.limitations,
        `Answer the retained question within its exact dated query and focus. ${REVIEW_INSTRUCTIONS}`, priorityIds);
      const result = await synthesizeReview(progress, input, {signal: stopped.signal,
        reserve: async value => {
          const reserved = await db.rpc("reserve_financial_investigation_synthesis", {p_job_id: jobId, p_workspace_id: workspaceId, p_run_id: runId, p_progress: value});
          if (reserved.error) throw reserved.error;
          if (typeof reserved.data !== "boolean") throw new FatalError("Invalid synthesis reservation receipt");
          return reserved.data;
        }, generate: options => generateText({model, ...options})});
      if (monitoringError) throw monitoringError;
      if (!await enterStage(db, jobId, workspaceId, runId, "writing_review")) return null;
      return reviewBody(result.text, [result.limitation], prioritizeReviewReceipts(receipts, priorityIds), workspaceId);
    }
    const result = await generateText({ model, maxOutputTokens: 4000, maxRetries: 0, abortSignal: AbortSignal.any([stopped.signal, AbortSignal.timeout(90_000)]),
      system: `Write a personal-finance review of the supplied dated evidence. Cover cashflow, material changes, budgets, obligations, goals, wealth/debt and forecasts when measures are available. ${REVIEW_INSTRUCTIONS}`,
      prompt: JSON.stringify({ datedReviewSnapshot: evidence, evidenceReceipts: receipts.map(receipt => ({ id: receipt.id, metrics: receipt.metrics.map(withFormattedValue) })) }) });
    if (monitoringError) throw monitoringError;
    if (!await enterStage(db, jobId, workspaceId, runId, "writing_review")) return null;
    return reviewBody(result.text, [result.finishReason === "length" ? "Incomplete review: the provider reached its output limit; further findings may be missing." : null], receipts, workspaceId);
  } catch (error) {
    // Awaiting generateText above ensures its application transport has settled
    // before a cancellation can become acknowledged in the application row.
    if (stopped.signal.aborted && !monitoringError && !await enterStage(service(), jobId, workspaceId, runId, "writing_review")) return null;
    retryFailure(error);
  } finally {
    finished.abort();
    await monitoring;
  }
}

